struct range { int64_t lob, upb; };   /* inclusive bounds */

static inline bool range_contains(const struct range *r, int64_t v)
{
    return v >= r->lob && v <= r->upb;
}

static inline bool range_overlaps(const struct range *a, const struct range *b)
{
    return !(b->upb < a->lob || a->upb < b->lob);
}
